{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Events — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--accent:#7bd389;--muted:#9aa6b2;--glass: rgba(255,255,255,0.04);--txt:#e8eef6}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial;color:var(--txt);background:linear-gradient(180deg,#071018 0%, #071520 45%), url('assets/img/pattern.svg');background-size:600px}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(4px)}
    .brand{font-weight:700;letter-spacing:0.6px}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:14px}
    .wrap{max-width:1100px;margin:28px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:22px;align-items:center}
    .hero .lead{background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:10px}
    h1{margin:0 0 8px;font-size:28px}
    p.lead-desc{margin:0;color:var(--muted)}
    .next-event{background:var(--card);padding:18px;border-radius:10px;color:var(--txt)}
    .meta{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
    .calendar-list{margin-top:20px;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
    .evt{background:var(--glass);padding:14px;border-radius:8px}
    .seat-map{margin-top:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:12px;border-radius:8px}
    .seats{display:flex;gap:8px;flex-wrap:wrap}
    .seat{padding:8px 10px;border-radius:8px;background:#071827;border:1px solid rgba(255,255,255,0.03);cursor:pointer}
    .seat.selected{outline:2px solid var(--accent);background:linear-gradient(180deg, rgba(123,211,137,0.08), transparent)}
    .packing{margin-top:12px;padding:12px;background:#06111a;border-radius:8px;color:var(--muted)}
    .cta{display:inline-block;background:var(--accent);color:#062017;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    footer{margin-top:30px;padding:18px;color:var(--muted);font-size:13px}
    .disclaimer{margin-top:14px;font-size:13px;color:#f4b4b4}
    button.copy{background:#10202a;border:none;color:var(--txt);padding:8px 10px;border-radius:8px;cursor:pointer}
    @media(max-width:800px){.hero{grid-template-columns:1fr}nav a{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private Immersions</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Our Story</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Book a Date</a>
      <a href="contact.html">Reach Us</a>
    </nav>
  </header>
  <main class="wrap">
    <section class="hero">
      <div class="lead">
        <h1>Community Sound Gatherings</h1>
        <p class="lead-desc">Join short-form and extended sessions that chart a clear arc: arrival, attunement, and a sound-led closing. Seats are limited to keep the field intimate.</p>
        <div style="margin-top:12px">
          <a class="cta" href="book.html">Reserve On the Calendar</a>
        </div>
      </div>
      <aside class="next-event">
        <strong>Next Event</strong>
        <div id="nextEventCard" style="margin-top:10px">
          <!-- populated by JS -->
        </div>
      </aside>
    </section>

    <section style="margin-top:18px">
      <h2 style="margin:0 0 10px">Upcoming Dates</h2>
      <div class="calendar-list" id="calendarList">
        <!-- populated by JS -->
      </div>
    </section>

    <section style="margin-top:18px">
      <h3 style="margin:0 0 8px">Select a Seat — Try the quick planner</h3>
      <div class="evt">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:700" id="selectedEventTitle">—</div>
            <div style="font-size:13px;color:var(--muted)" id="selectedEventWhen">—</div>
          </div>
          <div id="seatCount">Available: —</div>
        </div>

        <div class="seat-map" id="seatMap">
          <div style="font-size:13px;color:var(--muted)">Pick a seat type</div>
          <div class="seats" id="seatOptions">
            <button class="seat" data-type="floor">Floor Cushion</button>
            <button class="seat" data-type="mat">Yoga Mat</button>
            <button class="seat" data-type="chair">Chair</button>
          </div>

          <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
            <label style="font-size:13px;color:var(--muted)">Quantity</label>
            <input id="seatQty" type="number" min="1" max="6" value="1" style="width:64px;padding:6px;border-radius:6px;border:1px solid rgba(255,255,255,0.04);background:#06111a;color:var(--txt)">
            <button id="reserveBtn" class="cta">Reserve Spot</button>
          </div>

          <div class="packing" id="packingList">
            <strong>What to bring</strong>
            <div id="packingItems" style="margin-top:8px;color:var(--muted)">Choose a seat and quantity to see suggestions.</div>
          </div>
        </div>
      </div>
    </section>

    <div class="disclaimer">
      Contraindications: Sound baths involve sustained low-frequency tones and deep relaxation. If you are pregnant, have uncontrolled epilepsy, a pacemaker, or a history of seizure, please consult your physician before attending. If you have recent surgery or acute injury, check with your care provider.
    </div>

  </main>
  <footer>
    Questions? Call {{PHONE}} • {{EMAIL}} • Serving {{CITY}}, {{STATE}}
  </footer>

  <script>
    // Mock event data
    const events = [
      {id:1,title:'Evening Drift — Short Wave',date:'2026-02-28T19:00:00',duration:50,capacity:28,booked:12},
      {id:2,title:'Noon Field — Midday Pause',date:'2026-03-05T12:30:00',duration:60,capacity:30,booked:5},
      {id:3,title:'Deep Sunday — Extended',date:'2026-03-15T17:00:00',duration:90,capacity:24,booked:20},
      {id:4,title:'Morning Reset — Gentle Start',date:'2026-03-21T09:30:00',duration:45,capacity:20,booked:2}
    ];

    function formatDate(iso){
      const d=new Date(iso);
      return d.toLocaleString(undefined,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
    }

    function findNextEvent(){
      const now = Date.now();
      return events.find(e=>new Date(e.date).getTime()>now) || events[0];
    }

    const next = findNextEvent();
    const nextCard = document.getElementById('nextEventCard');
    nextCard.innerHTML = `<div style=\"font-weight:700\">${next.title}</div><div style=\"color:var(--muted);font-size:13px;margin-top:6px\">${formatDate(next.date)} · ${next.duration} min</div><div style=\"margin-top:10px;display:flex;gap:8px\"><a class=\"cta\" href=\"book.html?event=${next.id}\">Reserve</a></div>`;

    // Populate calendar list
    const calendarList = document.getElementById('calendarList');
    calendarList.innerHTML = events.map(e=>{
      const seatsLeft = Math.max(0,e.capacity-e.booked);
      return `<div class=\"evt\"><div style=\"font-weight:700\">${e.title}</div><div style=\"color:var(--muted);font-size:13px;margin-top:6px\">${formatDate(e.date)} · ${e.duration} min</div><div style=\"margin-top:8px;display:flex;justify-content:space-between;align-items:center\"><div style=\"font-size:13px;color:var(--muted)\">Seats left: ${seatsLeft}</div><div><button class=\"cta small\" onclick=\"selectEvent(${e.id})\">Select</button></div></div></div>`;
    }).join('');

    // Seat selection logic
    const seatOptions = document.querySelectorAll('.seat');
    let chosenSeatType = null;
    seatOptions.forEach(btn=>btn.addEventListener('click', ()=>{
      seatOptions.forEach(b=>b.classList.remove('selected'));
      btn.classList.add('selected');
      chosenSeatType = btn.getAttribute('data-type');
      renderPacking();
    }));

    const seatQty = document.getElementById('seatQty');
    const packingItems = document.getElementById('packingItems');
    const seatCount = document.getElementById('seatCount');
    let activeEvent = next;

    function selectEvent(id){
      activeEvent = events.find(e=>e.id===id);
      document.getElementById('selectedEventTitle').textContent = activeEvent.title;
      document.getElementById('selectedEventWhen').textContent = formatDate(activeEvent.date) + ' · ' + activeEvent.duration + ' min';
      seatCount.textContent = 'Available: '+ Math.max(0, activeEvent.capacity-activeEvent.booked);
      renderPacking();
      window.scrollTo({top:document.querySelector('.evt').offsetTop-10,behavior:'smooth'});
    }

    // Init with next
    selectEvent(next.id);

    function renderPacking(){
      const qty = parseInt(seatQty.value||1,10);
      if(!chosenSeatType){
        packingItems.textContent = 'Choose a seat type above to get a tailored list.';
        return;
      }
      const common = ['Reusable water bottle','Warm blanket','Comfortable clothing','Optional eye mask'];
      const seatSpecific = {
        floor:['Thin floor cushion or bolster','Socks with grip'],
        mat:['Yoga mat or exercise mat','Small towel for head support'],
        chair:['Portable seat pad','Scarf or shawl for neck support']
      }[chosenSeatType] || [];

      const timeNotes = activeEvent.duration>60 ? ['Consider extra layers for longer sessions'] : ['Shorter session — arrive 10 minutes early to settle'];
      const list = common.concat(seatSpecific).concat(timeNotes);
      packingItems.innerHTML = '<ul style="margin:6px 0 0 18px;color:var(--muted)">'+list.map(i=>'<li>'+i+'</li>').join('')+`</ul><div style=\"margin-top:8px;color:var(--muted)\">Quantity: ${qty}</div>`;
    }

    seatQty.addEventListener('input', renderPacking);

    document.getElementById('reserveBtn').addEventListener('click', ()=>{
      const seatsLeft = Math.max(0, activeEvent.capacity-activeEvent.booked);
      const qty = Math.min(parseInt(seatQty.value||1,10), seatsLeft);
      if(qty<=0){
        alert('No seats available for this event.');
        return;
      }
      const seatLabel = chosenSeatType ? chosenSeatType : 'general';
      const summary = `I want to reserve ${qty} x ${seatLabel} for \nEvent: ${activeEvent.title} \nWhen: ${formatDate(activeEvent.date)}\nDuration: ${activeEvent.duration} min\nPlease contact me: ${'{{PHONE}}'} or ${'{{EMAIL}}'}`;
      navigator.clipboard && navigator.clipboard.writeText(summary).then(()=>{
        alert('Reservation draft copied to clipboard. Use our Book page to complete.');
      });
    });

  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#041018;--panel:#07171f;--accent:#6ad1f7;--muted:#9fb6c4;--txt:#e6f4fb}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial;background:linear-gradient(180deg,#031016 0%,#041021 100%);color:var(--txt)}
    header{padding:18px 24px;display:flex;justify-content:space-between;align-items:center;background:rgba(255,255,255,0.02)}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px}
    .wrap{max-width:960px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .panel{background:var(--panel);padding:18px;border-radius:10px}
    h1{margin:0 0 8px}
    label{display:block;margin-top:10px;font-size:13px;color:var(--muted)}
    input[type=text],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:#021318;color:var(--txt)}
    .btn{background:var(--accent);color:#012;display:inline-block;padding:10px 12px;border-radius:8px;border:none;cursor:pointer;font-weight:700}
    .summary{white-space:pre-wrap;background:#021319;padding:12px;border-radius:8px;margin-top:12px;color:var(--muted)}
    .small{font-size:13px;color:var(--muted)}
    .disclaimer{margin-top:12px;color:#f5b4b4;font-size:13px}
    @media(max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private Immersions</a>
      <a href="pricing.html">Investment</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="panel">
        <h1>Private Immersions — Personal Plan Builder</h1>
        <p class="small">Tailor a short roadmap for a private session. Generate a plaintext plan you can copy or download and share when booking.</p>

        <label for="clientName">Your name</label>
        <input id="clientName" type="text" placeholder="First and last">

        <label for="focus">Primary focus</label>
        <select id="focus">
          <option value="sleep">Sleep support</option>
          <option value="stress">Stress reduction</option>
          <option value="recovery">Physical recovery</option>
          <option value="clarity">Focus & clarity</option>
          <option value="creative">Creative facilitation</option>
        </select>

        <label for="duration">Duration (minutes)</label>
        <select id="duration">
          <option>45</option>
          <option selected>60</option>
          <option>90</option>
          <option>120</option>
        </select>

        <label>Instruments preferred</label>
        <div style="display:flex;gap:8px;margin-top:6px">
          <label style="font-size:13px"><input type="checkbox" value="Crystal bowls"> Crystal bowls</label>
          <label style="font-size:13px"><input type="checkbox" value="Gong"> Gong</label>
          <label style="font-size:13px"><input type="checkbox" value="Voice"> Voice</label>
          <label style="font-size:13px"><input type="checkbox" value="Flute"> Flute</label>
        </div>

        <label style="margin-top:12px">Environment & extras</label>
        <div style="display:flex;gap:8px;margin-top:6px">
          <label style="font-size:13px"><input type="checkbox" value="dim"> Dim lights</label>
          <label style="font-size:13px"><input type="checkbox" value="candles"> Candles</label>
          <label style="font-size:13px"><input type="checkbox" value="recline"> Reclining setup</label>
          <label style="font-size:13px"><input type="checkbox" value="record"> Audio recording</label>
        </div>

        <label for="outcome">Desired outcome — short note</label>
        <textarea id="outcome" rows="3" placeholder="e.g. sleep through the night, calm nerves before presentation"></textarea>

        <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
          <button id="generate" class="btn">Build My Plan</button>
          <button id="download" class="btn" style="background:#2b8ea4">Download TXT</button>
          <button id="copyBtn" class="btn" style="background:#6ad18f">Copy Summary</button>
        </div>

        <div id="summary" class="summary">Your personalized session summary will appear here.</div>

        <div class="disclaimer">Contraindications: Private immersions are deeply relaxing. If pregnant, have implanted devices, epilepsy, or recent surgery, consult your clinician before booking.</div>
      </section>

      <aside class="panel">
        <h3 style="margin-top:0">What we include</h3>
        <ul style="color:var(--muted);padding-left:18px">
          <li>Pre-session intake and intention-setting</li>
          <li>Curated instrumentation and pacing</li>
          <li>Breath cues and gentle transitions</li>
          <li>Optional recording for personal use</li>
        </ul>

        <div style="margin-top:14px">
          <strong>VIP Day</strong>
          <p class="small" style="margin-top:6px;color:var(--muted)">Full-day immersive design for teams or individuals: extended sound practice, coaching, and takeaways. Request via our Investment page.</p>
          <a class="btn" href="pricing.html" style="display:inline-block;margin-top:8px">Request VIP Day</a>
        </div>

        <div style="margin-top:18px;color:var(--muted);font-size:13px">
          Quick contact: <br>{{PHONE}}<br>{{EMAIL}}
        </div>
      </aside>
    </div>
  </main>

  <script>
    function collectPlan(){
      const name = document.getElementById('clientName').value || 'Client';
      const focus = document.getElementById('focus').value;
      const duration = document.getElementById('duration').value;
      const checks = Array.from(document.querySelectorAll('input[type=checkbox]:checked')).map(i=>i.value);
      const outcome = document.getElementById('outcome').value || 'General balance and ease';

      const intro = `Personal Session Plan — ${name}\n`;
      const core = `Focus: ${focus}\nDuration: ${duration} minutes\nSelected extras: ${checks.length?checks.join(', '):'None'}\n\nIntended outcome:\n${outcome}\n`;
      const structure = `Planned flow:\n1) Arrival + intention setting (5-10 min)\n2) Anchoring breath + tone introduction (5-10 min)\n3) Main immersion (${duration} min) — dynamic layering, subtle crescendos\n4) Gentle return + integration notes (5-10 min)\n`;

      const logistics = `Notes: Bring water, blanket, comfortable clothing. Recording: ${checks.includes('record')?'Yes':'No'}.\nContact: ${'{{PHONE}}'} / ${'{{EMAIL}}'}`;

      return intro+core+'\n'+structure+'\n'+logistics;
    }

    const summaryEl = document.getElementById('summary');
    document.getElementById('generate').addEventListener('click', ()=>{
      const text = collectPlan();
      summaryEl.textContent = text;
    });

    document.getElementById('copyBtn').addEventListener('click', ()=>{
      const text = collectPlan();
      navigator.clipboard.writeText(text).then(()=>{
        alert('Plan copied to clipboard. Paste it into your booking or an email to us.');
      });
    });

    document.getElementById('download').addEventListener('click', ()=>{
      const text = collectPlan();
      const blob = new Blob([text],{type:'text/plain'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    });
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071017;--card:#08151b;--accent:#ffb86b;--muted:#9cb1bb;--txt:#f6efe9}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial;background:linear-gradient(180deg,#04121a,#071017);color:var(--txt)}
    header{padding:16px 22px;display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    .wrap{max-width:980px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:var(--card);padding:16px;border-radius:10px}
    h1{margin:0 0 10px}
    .price{font-weight:800;font-size:22px;margin-top:8px}
    .row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-top:1px solid rgba(255,255,255,0.03)}
    .muted{color:var(--muted)}
    .calc input[type=number]{width:80px;padding:8px;border-radius:8px;border:none;background:#03141a;color:var(--txt)}
    .btn{background:var(--accent);color:#2a1606;padding:10px 12px;border-radius:8px;border:none;cursor:pointer;font-weight:700}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    .disclaimer{margin-top:12px;color:#f4b4b4;font-size:13px}
    @media(max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private Immersions</a>
      <a href="pricing.html">Investment</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Investment & Packages</h1>
    <p class="muted">Clear pricing, modular add-ons, and a VIP Day offering for teams and deep renewal.</p>

    <div class="grid">
      <section>
        <div class="card">
          <h3 style="margin:0">Pulse Intro</h3>
          <div class="price">$45 — 45 minutes</div>
          <p class="note">A concise group practice for beginners or a focused top-up.</p>
          <div style="margin-top:10px"><a class="btn" href="book.html">Book Intro</a></div>
        </div>

        <div class="card" style="margin-top:14px">
          <h3 style="margin:0">Deep Field</h3>
          <div class="price">$95 — 90 minutes</div>
          <p class="note">Expanded sound arc with space for integration and brief reflection.</p>
          <div style="margin-top:10px"><a class="btn" href="book.html">Reserve Deep Field</a></div>
        </div>

        <div class="card" style="margin-top:14px">
          <h3 style="margin:0">Focused Resonance — VIP Day</h3>
          <div class="price">Custom pricing — full day</div>
          <p class="note">A tailored, off-calendar day: team installations, private sound steering, and hands-on practice design. This is our VIP Day model.</p>
          <div style="margin-top:10px"><a class="btn" href="book.html?vip=1">Request VIP Day</a></div>
        </div>

        <div class="card" style="margin-top:14px">
          <h3 style="margin:0">Private Session (Solo)</h3>
          <div class="price">Base $150 — 60 minutes</div>
          <p class="note">Includes intake and optional recording. Add travel for off-site work.</p>
        </div>

        <div class="disclaimer">Contraindications: If you have implanted medical devices, uncontrolled epilepsy, are pregnant without medical approval, or have recent surgical wounds, please check with a clinician before attending. We will always accommodate questions and adapt practice where possible.</div>
      </section>

      <aside class="card">
        <h3 style="margin-top:0">Price calculator</h3>
        <div class="calc" style="margin-top:10px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><div>Session type</div><select id="pkg"><option value="intro">Pulse Intro</option><option value="deep">Deep Field</option><option value="private">Private 60m</option><option value="vip">VIP Day</option></select></div>
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><div>Participants</div><input id="participants" type="number" min="1" value="1"></div>
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><div>Recording</div><input id="recording" type="checkbox"></div>
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><div>Travel fee</div><input id="travel" type="checkbox"></div>

          <div class="row"><div style="color:var(--muted)">Estimated total</div><div id="total" style="font-weight:800">$0</div></div>

          <div style="margin-top:12px">
            <button id="calcBtn" class="btn">Calculate</button>
            <a id="ctaBtn" class="btn" style="background:#9bc95a;margin-left:8px" href="book.html">Proceed to Book</a>
          </div>

          <div class="note">VIP Day pricing is custom; calculation will show an estimated deposit. For exact scope and timing, request a proposal.</div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    const base = {intro:45,deep:95,private:150,vip:1200}; // vip is a base-day estimate
    function compute(){
      const pkg = document.getElementById('pkg').value;
      const pCount = Math.max(1,parseInt(document.getElementById('participants').value||1,10));
      const rec = document.getElementById('recording').checked;
      const travel = document.getElementById('travel').checked;
      let total = 0;
      if(pkg==='intro') total = base.intro;
      if(pkg==='deep') total = base.deep;
      if(pkg==='private') total = base.private + (pCount>1?(pCount-1)*20:0);
      if(pkg==='vip') total = base.vip + (pCount-1)*75;
      if(rec) total += 25;
      if(travel) total += 40;
      return total;
    }

    document.getElementById('calcBtn').addEventListener('click', ()=>{
      const total = compute();
      document.getElementById('total').textContent = '$'+total;
